    .values({
      id: newId(),
      orgId,
      subjectKind,
      subjectId,
      projectId,
      content,
      indexedAt,
    })
    .run();
}

export async function deleteSearchDocument(
  orgId: OrgId,
  subjectKind: SearchSubjectKind,
  subjectId: string,
): Promise<void> {
