export async function findNotificationById(
  orgId: OrgId,
  notificationId: NotificationId,
): Promise<Notification | null> {
  const row = getDb()
    .select()
    .from(notifications)
    .where(
      and(
        orgPredicate(notifications.orgId, orgId),
        eq(notifications.id, notificationId),
      ),
    )
    .get();
  return row ? toNotification(row) : null;
}

/**
 * True when this recipient already has an unread alert of `kind` whose body
 * is exactly `body`. Used to collapse repeated plan-limit refusals.
 */
export async function hasUnreadWithBody(
  orgId: OrgId,
  recipientId: UserId,
  kind: NotificationKind,
  body: string,
): Promise<boolean> {
  const row = getDb()
    .select({ id: notifications.id })
    .from(notifications)
    .where(
      and(
        orgPredicate(notifications.orgId, orgId),
        eq(notifications.recipientId, recipientId),
        eq(notifications.kind, kind),
        eq(notifications.body, body),
        isNull(notifications.readAt),
      ),
    )
    .get();
  return row !== undefined;
}

