/**
 * One unread plan-limit alert per resource. A later refusal for that same
 * resource adds nothing until the owner has read the open one. The usage
 * recount never calls this — only a write that was actually refused does.
 */
export async function notifyPlanLimitReached(
  orgId: OrgId,
  resource: LimitedResource,
): Promise<void> {
  const org = await orgRepo.findOrgById(orgId);
  if (!org) return;

  const body = `resource:${resource}`;
  const alreadyOpen = await notificationRepo.hasUnreadWithBody(
    orgId,
    org.ownerId,
    "plan_limit_reached",
    body,
  );
  if (alreadyOpen) return;

  await notify(orgId, "plan_limit_reached", [org.ownerId], {
    title: "Your plan is full",
    body,
    href: settingsPath(org.slug, "billing"),
    actorId: null,
  });
}

/** Inboxes and preference rows belong to one member, whatever their role. */
function assertOwnNotifications(actor: Actor, userId: UserId): void {
  if (actor.userId === userId) return;
  throw new PermissionDeniedError("notification:read", {
    action: "notification:read",
    resourceKind: "notification",
    allowed: false,
    reason: "denied_by_role",
  });
}

