async function hrefFor(
  orgId: OrgId,
  kind: SearchSubjectKind,
  subjectId: string,
): Promise<string> {
  const org = await orgRepo.findOrgById(orgId);
  const orgSlug = org?.slug ?? orgId;

  if (kind === "project") {
    const project = await projectRepo.findProjectById(
      orgId,
      subjectId as ProjectId,
    );
    return project
      ? projectPath(orgSlug, project.slug)
      : orgPath(orgSlug, "projects", subjectId);
  }

  const issueId =
    kind === "issue"
      ? (subjectId as IssueId)
      : (
          await commentRepo.findCommentById(orgId, subjectId as CommentId)
        )?.issueId;

  if (!issueId) return orgPath(orgSlug, "issues");

  const issue = await issueRepo.findIssueById(orgId, issueId);
  if (!issue) return orgPath(orgSlug, "issues", issueId);
  const project = await projectRepo.findProjectById(orgId, issue.projectId);
  if (!project) return orgPath(orgSlug, "issues", issueId);
  return issuePath(orgSlug, project.slug, issue.number);
}

